vocabulary.leanSketch:
def letterWeight (T : Task) {n} (w : Fin n → T.Sym) : ℝ := ∏ t, (T.μ (w t)).toReal
def Ex (T : Task) {n} {E} [AddCommGroup E] [Module ℝ E] (f : (Fin n → T.Sym) → E) : E :=
  ∑ w, letterWeight T w • f w
